function live545_admin_upload_poster(): string {
    if(empty($_FILES['poster_file'])||!is_array($_FILES['poster_file'])||($_FILES['poster_file']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return '';
    $f=$_FILES['poster_file'];if(($f['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)throw new RuntimeException('Poster upload failed.');
    if((int)($f['size']??0)>8*1024*1024)throw new RuntimeException('Poster image must be under 8 MB.');
    $tmp=(string)($f['tmp_name']??'');if(!is_file($tmp))throw new RuntimeException('Invalid poster upload.');
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp)?:'';$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'][$mime]??'';if($ext==='')throw new RuntimeException('Poster must be JPG, PNG, WEBP or GIF.');
    $dir=__DIR__.'/../uploads/live';if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Could not create live upload directory.');
    $name='live-'.date('Ymd-His').'-'.bin2hex(random_bytes(5)).'.'.$ext;$dest=$dir.'/'.$name;if(!move_uploaded_file($tmp,$dest))throw new RuntimeException('Could not save poster image.');return '/uploads/live/'.$name;
}
function live545_admin_source(string $url,string $type): string {
    $url=trim($url);if($url==='')return '';
    if($type==='rtmp'&&(str_starts_with(strtolower($url),'rtmp://')||str_starts_with(strtolower($url),'rtmps://')))return $url;if($type==='rtsp'&&(str_starts_with(strtolower($url),'rtsp://')||str_starts_with(strtolower($url),'rtsps://')))return $url;
    $safe=live_v545_safe_url($url);if($safe==='')throw new RuntimeException('Source URL must be a valid http(s) URL'.($type==='rtmp'?' or RTMP URL.':'.'));return $safe;
}
function live545_dt(?string $v): ?string {$v=trim((string)$v);if($v==='')return null;$t=strtotime($v);return $t?date('Y-m-d H:i:s',$t):null;}

