   if($id>0){$b=live_v545_admin_find($id);if(!$b)throw new RuntimeException('Broadcast not found.');$params[]=$id;db()->prepare('UPDATE live_broadcasts_v545 SET tenant_id=?,city_id=?,title=?,slug=?,description=?,source_type=?,source_url=?,fallback_url=?,poster_url=?,category=?,status=?,is_featured=?,show_on_home=?,chat_enabled=?,analytics_enabled=?,autoplay_muted=?,start_at=?,end_at=?,sort_order=?,created_by=?,updated_at=NOW() WHERE id=?')->execute($params);$flash='Broadcast updated and public display refreshed.';}else{db()->prepare('INSERT INTO live_broadcasts_v545(tenant_id,city_id,title,slug,description,source_type,source_url,fallback_url,poster_url,category,status,is_featured,show_on_home,chat_enabled,analytics_enabled,autoplay_muted,start_at,end_at,sort_order,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())')->execute($params);$id=(int)db()->lastInsertId();$flash=$status==='live'?'Broadcast added and is now LIVE publicly.':'Broadcast added successfully.';}
